(globalThis.TURBOPACK||(globalThis.TURBOPACK=[])).push(["object"==typeof document?document.currentScript:void 0,64326,e=>{"use strict";let a={name:"Kitum Cave Safaris",tagline:"Discover Africa. Experience More Than the Journey.",description:"Curated travel experiences across Uganda, East Africa, and beyond. Authentic journeys crafted with local knowledge and premium care.",url:e.i(47167).default.env.NEXT_PUBLIC_SITE_URL||"https://kitumcavesafaris.com",email:"info@kitumcavesafaris.com",phone:"0705940988",whatsapp:"256705940988",whatsappDisplay:"0705940988",address:"Kiwatule, Kampala, IM Mall, C14, P.O. Box 214138, Kampala, Uganda",location:{lat:.365556,lng:32.625275,name:"IM Mall, C14, Kiwatule, Kampala"},legalName:"Kitum Cave Safaris Limited",ursbNumber:"80040097847752",utbLicense:"",officeHours:"Monday–Saturday, 8:00am–5:00pm (East Africa Time)",alwaysOn:"WhatsApp, email, socials, and online bookings are available 24/7.",social:{instagram:"https://www.instagram.com/kitumcavesafaris/",x:"https://x.com/kitumcavesafari",linkedin:"https://www.linkedin.com/company/kitum-cave-safaris/about/?viewAsMember=true",facebook:"https://www.facebook.com/share/19J47sjJx2/",tiktok:"https://www.tiktok.com/@infokitumcavesafar"},businessHours:"Office: Monday–Saturday, 8:00am–5:00pm (East Africa Time). WhatsApp, email, socials, and bookings: 24/7.",partialPaymentPercent:30,currency:"USD"},i=[{question:"What payment methods do you accept?",answer:"Visa/Mastercard, mobile money (MTN & Airtel), bank transfer, and international payment links via Flutterwave."},{question:"Can I pay in UGX, KES, USD, or EUR?",answer:"Yes — we quote and accept payment in multiple currencies. Display rates on the website are approximate until confirmed at booking."},{question:"When can I reach you?",answer:"The Kampala office is open Monday to Saturday, 8:00am to 5:00pm East Africa Time. WhatsApp, email, socials, and online bookings stay available around the clock."},{question:"Is travel insurance required?",answer:"We strongly recommend comprehensive travel insurance covering medical evacuation and trip cancellation."},{question:"Are lunch and dinner included?",answer:"Breakfast is included. Lunch and dinner are available throughout the journey at extra cost — lodges and restaurants along the route serve them, and we can help you arrange them."}],n=["Valid passport and travel documents","Comfortable neutral-coloured clothing","Sun hat, sunscreen, and insect repellent","Sturdy closed shoes","Reusable water bottle","Camera and binoculars (recommended)"],r=[{id:"gorilla-safari-3d",slug:"3-days-gorilla-safari",name:"3 Days Gorilla Safari",destination:"Bwindi Impenetrable National Park & Lake Bunyonyi",country:"Uganda",region:"east-africa",duration:"3 Days / 2 Nights",durationDays:3,price:1650,currency:"USD",priceNote:"Based on shared trekking; private upgrades available on request.",shortDescription:"Track mountain gorillas in Bwindi's ancient rainforest, then unwind on the terraced shores of Lake Bunyonyi.",fullDescription:"This three-day journey takes you deep into southwestern Uganda — from the mist-shrouded slopes of Bwindi Impenetrable National Park, a UNESCO World Heritage Site home to nearly half the world's remaining mountain gorillas, to the serene islands of Lake Bunyonyi. Guided by experienced rangers and our professional driver-guides, you'll traverse changing landscapes, cross the Equator, and witness one of Africa's most profound wildlife encounters.",travelType:"Wildlife & Nature",availability:"Available year-round — peak gorilla trekking Jun–Sep & Dec–Feb",bestTimeToVisit:"Gorilla trekking is possible year-round. Dry seasons (June–September and December–February) offer easier forest trails and clearer views. The wetter months can mean shorter treks but muddier paths — pack accordingly.",whatToBring:["Sturdy waterproof hiking boots","Long trousers and long-sleeved shirt (neutral colours)","Light rain jacket and daypack","Insect repellent and sun protection","Reusable water bottle","Camera (no flash during gorilla viewing)","Yellow fever certificate (recommended)"],faqs:[{question:"How fit do I need to be for gorilla trekking?",answer:"A moderate level of fitness is recommended. Treks can last 2–6 hours on steep, muddy terrain. Porters are available to hire locally for extra support."},{question:"Is the gorilla permit included?",answer:"Yes — your gorilla permit, park fees, and all activities listed in the itinerary are included in the package price."},{question:"What is the minimum age?",answer:"Uganda Wildlife Authority requires trekkers to be at least 15 years old."},{question:"Can I pay a deposit and settle the balance later?",answer:"Yes. A partial deposit secures your booking; the balance is due before travel as agreed with our team."}],heroImage:"/images/4A9A8590.jpg",galleryImages:["/images/4A9A8590.jpg","/images/4A9A8591.jpg","/images/4A9A8592.jpg","/images/4A9A8600.jpg","/images/4A9A8602.jpg","/images/4A9A8560.jpg","/images/4A9A8563.jpg","/images/4A9A8545.jpg"],mapCoordinates:{lat:-1.05,lng:29.65},mapZoom:8,included:["Gorilla permit","Park fees","4x4 Land Cruiser, fuel + driver-guide","Accommodation with daily breakfast","Mineral water","All activities mentioned in itinerary"],excluded:["International flights","Personal items","Tips","Soft drinks or alcohol","Optional activities"],itinerary:[{day:1,title:"Transfer to Bwindi Impenetrable National Park",description:"After breakfast, our professional safari guide-driver will pick you at your hotel or Entebbe International Airport for a scenic drive to Southwestern Uganda. The journey takes you through changing landscapes, local villages, rolling hills and lush countryside. You will have a stopover at the Equator crossing for photography and refreshments, followed by a lunch break en route in Mbarara or Kabale. In the late afternoon, arrive at Bwindi Impenetrable National Park, a UNESCO World Heritage Site and home to nearly half of the world's remaining mountain gorillas. The journey takes approximately 8-9 hours. Check in to your lodge, relax, and enjoy your dinner.",accommodation:"Bakiga Lodge"},{day:2,title:"Gorilla Trekking & Transfer to Lake Bunyonyi",description:"After an early morning breakfast, transfer to the park headquarters for a pre-trek briefing by Uganda Wildlife Authority rangers. Enter the dense rainforest with experienced guides and trackers in search of a habituated gorilla family. The trek may take 2-6 hours depending on gorilla movements. Once located, spend maximum unforgettable hours observing the gorillas in their natural habitat. After the trek, return to the lodge for lunch and a short rest. In the afternoon, depart Bwindi and drive to Lake Bunyonyi, known for its terraced hills and scenic islands. It takes approximately 1 hour. Arrival, check in at the lodge, relaxation.",accommodation:"Arcadia Lodge"},{day:3,title:"Lake Bunyonyi Canoeing & Departure",description:"After morning breakfast, you will go for a boat safari to explore the islands including Punishment Island, Bwama Island, Nyuyeera Island, Bushara Island, Kahugye Island. After boat safari, begin journey to Entebbe, driving through the scenic countryside of Southwestern Uganda. Lunch will be taken en route in Mbarara with refreshment stops along the way. It will take approximately 7-8 hours drive. Arrive in Entebbe in the evening for drop-off at your hotel or at the airport and that will make the end of our trip."}],accommodation:"Bakiga Lodge (Day 1), Arcadia Lodge (Day 2)",transport:"4x4 Land Cruiser with professional driver-guide",importantInfo:["Gorilla trekking requires a reasonable level of fitness","Minimum age for gorilla trekking is 15 years","Gorilla permits are limited — book as early as you can so we can secure your dates with Uganda Wildlife Authority.","Pack sturdy hiking boots, long trousers, and rain gear"],bookingRequirements:["Valid passport","Gorilla trekking permit (arranged by Kitum Cave Safaris)","Yellow fever vaccination certificate recommended"],cancellationPolicy:"Cancellations 60+ days before travel: deposit refundable minus admin fee. 30–59 days: 50% of deposit retained. Under 30 days: deposit non-refundable. Gorilla permits are non-transferable once issued — we will advise on case-by-case exceptions.",partialPaymentPercent:30,featured:!0,categories:["wildlife","adventure","nature"]},{id:"queen-elizabeth-safari",slug:"queen-elizabeth-wildlife-safari",name:"Queen Elizabeth Wildlife Safari",destination:"Queen Elizabeth National Park",country:"Uganda",region:"east-africa",duration:"4 Days / 3 Nights",durationDays:4,price:980,currency:"USD",priceNote:"Based on shared safari vehicle; private upgrades available on request.",shortDescription:"Game drives, Kazinga Channel boat safaris, and tree-climbing lions in Uganda's most diverse national park.",fullDescription:"Explore the Rift Valley landscapes of Queen Elizabeth National Park — from savannah game drives and the famous tree-climbing lions of Ishasha to a sunset cruise on the Kazinga Channel, where elephants, hippos, and birdlife gather at the water's edge. Our driver-guides handle permits, park fees, and lodge logistics so you can focus on the wildlife.",travelType:"Wildlife Safari",availability:"Available year-round — peak wildlife viewing Jun–Sep & Dec–Feb",bestTimeToVisit:"Wildlife viewing is rewarding year-round. Dry seasons (June–September and December–February) offer easier road access and clearer skies.",whatToBring:n,faqs:i,heroImage:"/images/4A9A0474.jpg",galleryImages:["/images/4A9A0474.jpg","/images/4A9A0486.jpg","/images/4A9A9703.jpg","/images/4A9A9717.jpg","/images/IMG-20260811-WA0099.jpg"],mapCoordinates:{lat:-.2,lng:30},mapZoom:9,included:["Park entrance fees","Game drives and Kazinga Channel boat safari","4x4 safari vehicle, fuel, and driver-guide","Accommodation with daily breakfast","Bottled water in the vehicle"],excluded:["International flights","Personal expenses and tips","Alcoholic drinks","Optional activities not listed"],itinerary:[{day:1,title:"Transfer to Queen Elizabeth National Park",description:"Depart Kampala or Entebbe for the western Rift Valley. Stop at the Equator for photos and lunch en route, then continue to Queen Elizabeth National Park for an evening at leisure.",accommodation:"Enganzi Game Lodge"},{day:2,title:"Morning game drive & Kazinga Channel cruise",description:"Early morning game drive on the Kasenyi plains, then an afternoon boat safari on the Kazinga Channel — one of Africa's richest hippo and bird habitats.",accommodation:"Enganzi Game Lodge"},{day:3,title:"Ishasha tree-climbing lions",description:"Drive south to the Ishasha sector in search of tree-climbing lions, with picnic lunch and varied savannah scenery along the way.",accommodation:"Enganzi Game Lodge"},{day:4,title:"Return to Entebbe",description:"Relaxed morning departure with refreshment stops en route. Arrive Entebbe or Kampala in the afternoon."}],accommodation:"Enganzi Game Lodge (3 nights)",transport:"4x4 safari vehicle with professional driver-guide",importantInfo:["Moderate fitness sufficient for game drives and short walks","Yellow fever certificate recommended for Uganda travel","Pack neutral-coloured clothing and binoculars"],bookingRequirements:["Valid passport","Travel insurance recommended"],cancellationPolicy:"Deposit refundable up to 45 days before departure minus admin fees. Cancellations within 45 days may forfeit deposit; full terms provided at booking.",partialPaymentPercent:30,featured:!0,categories:["wildlife","nature"]},{id:"murchison-falls-safari",slug:"murchison-falls-adventure",name:"Murchison Falls Adventure",destination:"Murchison Falls National Park",country:"Uganda",region:"east-africa",duration:"3 Days / 2 Nights",durationDays:3,price:850,currency:"USD",priceNote:"Based on shared safari vehicle; private upgrades available on request.",shortDescription:"Witness the Nile explode through a narrow gorge, then cruise past elephants, hippos, and crocodiles on Uganda's largest national park.",fullDescription:"Murchison Falls National Park delivers classic African safari drama — the Nile forcing through a seven-metre gorge, vast savannah game drives, and river cruises teeming with hippos and crocodiles. Our team arranges park fees, boat tickets, and comfortable lodge stays so your time in the park is spent watching wildlife, not worrying about logistics.",travelType:"Adventure & Wildlife",availability:"Available year-round — peak season Dec–Feb & Jun–Sep",bestTimeToVisit:"Game viewing is strong year-round. Dry seasons offer easier access to remote tracks and clearer views of the falls.",whatToBring:n,faqs:i,heroImage:"/images/4A9A0445.jpg",galleryImages:["/images/4A9A0445.jpg","/images/4A9A0449.jpg","/images/4A9A0451.jpg","/images/4A9A0453.jpg","/images/4A9A0460.jpg","/images/4A9A0462.jpg"],mapCoordinates:{lat:2.27,lng:31.68},mapZoom:9,included:["Park and boat cruise fees","Game drives on the northern bank","4x4 vehicle, fuel, and driver-guide","Accommodation with daily breakfast","Bottled water in the vehicle"],excluded:["International flights","Tips and personal items","Alcoholic beverages","Optional top-of-falls hike permit if added"],itinerary:[{day:1,title:"Transfer to Murchison Falls",description:"Drive north through changing countryside with a lunch stop en route. Evening arrival at the lodge overlooking the Nile.",accommodation:"Pakuba Safari Lodge"},{day:2,title:"Game drive & Nile boat cruise",description:"Morning game drive on the Buligi plains, then an afternoon boat cruise to the base of Murchison Falls — hippos, crocodiles, and waterbirds at close range.",accommodation:"Pakuba Safari Lodge"},{day:3,title:"Top of the falls & return",description:"Visit the top of Murchison Falls for dramatic views before driving back to Entebbe or Kampala."}],accommodation:"Pakuba Safari Lodge (2 nights)",transport:"4x4 safari vehicle with professional driver-guide",importantInfo:["Boat cruise schedules may shift with water levels — we confirm on arrival","Pack sun protection for open-top game drives"],bookingRequirements:["Valid passport","Travel insurance recommended"],cancellationPolicy:"Deposit refundable up to 45 days before departure minus admin fees. Cancellations within 45 days may forfeit deposit; full terms provided at booking.",partialPaymentPercent:30,featured:!0,categories:["adventure","wildlife","nature"]},{id:"kenya-masai-mara",slug:"kenya-masai-mara-safari",name:"Masai Mara Safari",destination:"Masai Mara National Reserve",country:"Kenya",region:"east-africa",duration:"4 Days / 3 Nights",durationDays:4,price:1890,currency:"USD",priceNote:"Based on shared safari vehicle; migration-season surcharges may apply.",shortDescription:"Golden savannah, big cats, and the Great Migration on the legendary plains of the Masai Mara.",fullDescription:"The Masai Mara is the Africa of imagination — wide grasslands, predator action, and seasonal river crossings during the Great Migration. We coordinate cross-border logistics from Uganda, reserve entry, and lodge bookings with experienced Mara guides who know where the wildlife is moving.",travelType:"Wildlife Safari",availability:"Available year-round — migration peaks Jul–Oct",bestTimeToVisit:"July to October for river crossings; January to March for calving season on the plains. Green season offers fewer crowds and excellent photography light.",whatToBring:n,faqs:i,heroImage:"/images/IMG-20260811-WA0021.jpg",galleryImages:["/images/IMG-20260811-WA0021.jpg","/images/IMG-20260811-WA0029.jpg","/images/IMG-20260811-WA0038.jpg","/images/IMG-20260811-WA0069.jpg","/images/IMG-20260811-WA0074.jpg","/images/IMG-20260811-WA0079.jpg"],mapCoordinates:{lat:-1.5,lng:35},mapZoom:8,included:["Masai Mara reserve fees","Daily game drives","Safari vehicle, fuel, and guide","Lodge accommodation with daily breakfast","Park and conservancy fees as listed"],excluded:["International and regional flights","Visa fees for Kenya","Personal expenses and tips","Balloon safari (optional add-on)"],itinerary:[{day:1,title:"Arrive Masai Mara",description:"Transfer from Nairobi or cross from Uganda by road or flight connection (as arranged). Afternoon game drive on the plains.",accommodation:"Mara Serena Safari Lodge"},{day:2,title:"Full-day game drives",description:"Full day on the Mara with picnic lunch, tracking predators and herds across the reserve.",accommodation:"Mara Serena Safari Lodge"},{day:3,title:"Mara River sector",description:"Focus on the Mara River area — prime territory for cats and, in season, migration crossings.",accommodation:"Mara Serena Safari Lodge"},{day:4,title:"Morning drive & departure",description:"Final sunrise game drive before transfer to your onward connection."}],accommodation:"Mara Serena Safari Lodge (3 nights)",transport:"4x4 safari vehicle with professional guide",importantInfo:["Kenya eTA required for most nationalities — apply before travel","Migration timing is nature-dependent; we advise on best windows when you book"],bookingRequirements:["Valid passport (6+ months validity)","Kenya eTA or visa as applicable"],cancellationPolicy:"Deposit refundable up to 45 days before departure minus admin fees. Cancellations within 45 days may forfeit deposit; full terms provided at booking.",partialPaymentPercent:30,featured:!0,categories:["wildlife","adventure"]},{id:"tanzania-serengeti",slug:"tanzania-serengeti-experience",name:"Serengeti Experience",destination:"Serengeti National Park",country:"Tanzania",region:"east-africa",duration:"5 Days / 4 Nights",durationDays:5,price:2450,currency:"USD",priceNote:"Based on shared safari vehicle; peak migration dates priced on request.",shortDescription:"Endless plains, predator action, and the rhythm of the Great Migration in Tanzania's iconic Serengeti.",fullDescription:"The Serengeti ecosystem defines the safari dream — vast horizons, year-round wildlife, and the circular journey of the Great Migration. We handle Tanzania park fees, lodge reservations, and guiding so you experience the central and northern Serengeti at the right season for your interests.",travelType:"Wildlife Safari",availability:"Available year-round — migration varies by month and sector",bestTimeToVisit:"June–October for northern Serengeti crossings; December–March for southern plains and calving. Shoulder seasons offer excellent value.",whatToBring:n,faqs:i,heroImage:"/images/IMG-20260811-WA0034.jpg",galleryImages:["/images/IMG-20260811-WA0034.jpg","/images/IMG-20260811-WA0025.jpg","/images/IMG-20260811-WA0046.jpg","/images/IMG-20260811-WA0050.jpg","/images/IMG-20260811-WA0054.jpg","/images/IMG-20260811-WA0062.jpg"],mapCoordinates:{lat:-2.33,lng:34.83},mapZoom:8,included:["Serengeti park fees and concession fees","Daily game drives","Safari vehicle, fuel, and guide","Lodge or tented camp accommodation with daily breakfast","Bottled water in the vehicle"],excluded:["International flights","Tanzania visa on arrival or eVisa","Tips and personal expenses","Optional balloon safari"],itinerary:[{day:1,title:"Arrive Serengeti",description:"Transfer from Arusha or regional connection into the Serengeti. Afternoon game drive as you settle into the plains.",accommodation:"Serengeti Serena Safari Lodge"},{day:2,title:"Central Serengeti game drives",description:"Full-day exploration of the central Seronera region — strong predator territory year-round.",accommodation:"Serengeti Serena Safari Lodge"},{day:3,title:"Northern or southern sector",description:"Drive to the sector best suited to the season — river crossings in the north or calving plains in the south.",accommodation:"Serengeti Serena Safari Lodge"},{day:4,title:"Full-day safari",description:"Extended game drive with picnic lunch, following recent wildlife movements with your guide.",accommodation:"Serengeti Serena Safari Lodge"},{day:5,title:"Sunrise drive & departure",description:"Final morning on the plains before transfer to Arusha or your onward flight."}],accommodation:"Serengeti Serena Safari Lodge (4 nights)",transport:"4x4 safari vehicle with professional guide",importantInfo:["Migration routes shift monthly — we recommend dates based on your priorities","Yellow fever certificate may be required depending on travel route"],bookingRequirements:["Valid passport (6+ months validity)","Tanzania visa or eVisa as applicable"],cancellationPolicy:"Deposit refundable up to 45 days before departure minus admin fees. Cancellations within 45 days may forfeit deposit; full terms provided at booking.",partialPaymentPercent:30,featured:!0,categories:["wildlife","adventure","nature"]},{id:"zanzibar-5-day-trip",slug:"5-days-zanzibar-trip",name:"5 Days Zanzibar Trip",destination:"Stone Town & Nungwi Beach, Zanzibar",country:"Tanzania",region:"east-africa",duration:"5 Days / 4 Nights",durationDays:5,price:1097,currency:"USD",priceNote:"Per person sharing, high season. Includes round-trip flights Entebbe–Zanzibar. Optional activities priced separately.",shortDescription:"Stone Town heritage, Prison Island tortoises, Nakupenda sandbank, Safari Blue snorkeling, and Nungwi beach — with flights from Entebbe included.",fullDescription:"This five-day Zanzibar escape pairs UNESCO-listed Stone Town with the white sands of Nungwi in the north. Fly from Entebbe to Abeid Amani Karume International Airport, then explore winding alleys, spice-scented markets, and Indian Ocean excursions — from giant tortoises on Prison Island and a BBQ lunch on Nakupenda sandbank to swimming with sea turtles and a full-day Safari Blue boat trip. Kitum Cave Safaris handles flights, transfers, guided tours, and hand-picked accommodation at Maru Maru Hotel and Amaan Beach Bungalows so you can focus on the island.",travelType:"Beach & Culture",availability:"Available year-round — contact us for flight dates and high-season availability",bestTimeToVisit:"June to October and December to February offer the driest beach weather. March–May is greener with fewer crowds; we advise on seasonal rates when you book.",whatToBring:["Valid passport and Tanzania visa or eVisa","Light beachwear and modest clothing for Stone Town","Reef-safe sunscreen, sun hat, and sunglasses","Swimwear and snorkel gear (optional — provided on Safari Blue)","Insect repellent and reusable water bottle","Waterproof bag for boat excursions","Travel insurance documents"],faqs:[{question:"Are flights from Entebbe included?",answer:"Yes — round-trip flights between Entebbe and Zanzibar are included in the package price quoted per person sharing."},{question:"What optional activities are available in Nungwi?",answer:"Popular add-ons include a sunset dhow cruise (from $25–30 pp), horse riding ($40 pp), and spa treatments at your resort. These are not included unless requested at booking."},{question:"Is accommodation on a sharing basis?",answer:"Yes — the quoted rate is per person on a sharing basis. Single-room supplements can be arranged on request."},{question:"Do I need a visa for Tanzania?",answer:"Most travellers require a Tanzania visa or eVisa. Visa fees are not included in the package — we advise on the latest requirements when you book."},...i.slice(0,1)],heroImage:"/images/IMG-20260811-WA0012.jpg",galleryImages:["/images/IMG-20260811-WA0012.jpg","/images/IMG-20260811-WA0015.jpg","/images/IMG-20260811-WA0016.jpg","/images/IMG-20260811-WA0018.jpg","/images/IMG-20260811-WA0022.jpg","/images/IMG-20260811-WA0059.jpg"],mapCoordinates:{lat:-6.16,lng:39.2},mapZoom:10,included:["4 nights accommodation — Maru Maru Hotel & Amaan Beach Bungalows","Daily breakfast","Round-trip flights Entebbe–Zanzibar","Airport and inter-hotel transfers","Stone Town guided walking tour","Prison Island and Nakupenda sandbank excursion","Swimming with sea turtles (Mbarakumu caves, Kiwengwa)","Full-day Safari Blue boat trip (snorkeling, Kwale Island, mangrove lagoon)","Kwale Island and mangrove lagoon visit","Park and conservation fees","All activities listed in the itinerary"],excluded:["Tanzania visa fees","Travel insurance","Personal expenses (laundry, alcohol, tips)","Optional activities (sunset dhow cruise, horse riding, spa)","Activities not mentioned in the itinerary"],itinerary:[{day:1,title:"Arrival in Zanzibar & Stone Town Tour",description:"Morning or afternoon arrival at Abeid Amani Karume International Airport (ZNZ). Private transfer to Stone Town and check-in at the hotel. In the afternoon, enjoy a guided walking tour through Stone Town — Old Fort, Sultan's Palace, and Freddie Mercury House. Dinner at the hotel and overnight in Stone Town.",accommodation:"Maru Maru Hotel",meals:"Breakfast"},{day:2,title:"Prison Island, Nakupenda Sandbank & Sea Turtles",description:"After breakfast at the hotel, take a boat excursion to Prison Island to see giant tortoises and snorkel the surrounding reef. Continue by boat to Nakupenda sandbank for a BBQ lunch. In the afternoon, visit Mbarakumu caves at Kiwengwa to swim with wild sea turtles in natural limestone pools. Return to Stone Town for dinner and overnight.",accommodation:"Maru Maru Hotel",meals:"Breakfast"},{day:3,title:"Transfer to Nungwi Beach",description:"Breakfast and check-out, then a scenic transfer to Nungwi Beach (approximately 1.5 hours). Check in to your beach resort and enjoy free time for swimming and relaxation. Optional activities available: dhow sunset cruise ($30 pp), horse riding ($40 pp), or spa treatments. Dinner and overnight at Nungwi.",accommodation:"Amaan Beach Bungalows",meals:"Breakfast"},{day:4,title:"Safari Blue Full-Day Boat Trip",description:"Early morning breakfast, then transfer to Fumba/Menai Bay (approximately 45 minutes). Embark on the full-day Safari Blue experience — snorkeling at coral reefs, sandbank BBQ seafood lunch with tropical fruits and drinks, and a visit to Kwale Island and the mangrove lagoon. Return to the hotel for a free evening and dinner at the resort.",accommodation:"Amaan Beach Bungalows",meals:"Breakfast"},{day:5,title:"Departure",description:"Breakfast and check-out. Time to relax before your private transfer to Zanzibar Airport for your flight back to Entebbe — end of trip.",meals:"Breakfast"}],accommodation:"Maru Maru Hotel, Stone Town (2 nights) · Amaan Beach Bungalows, Nungwi (2 nights)",transport:"Round-trip flights Entebbe–Zanzibar; private airport and resort transfers; boat excursions as per itinerary",importantInfo:["Quoted rate is per person on a sharing basis (high season)","Optional add-ons: sunset dhow cruise from $25–30 pp, horse riding $40 pp","Safari Blue and boat trips are weather-dependent — we reschedule when needed","Pack modest clothing for Stone Town and reef-safe sunscreen for snorkeling"],bookingRequirements:["Valid passport (6+ months validity)","Tanzania visa or eVisa","Travel insurance strongly recommended"],cancellationPolicy:"Deposit refundable up to 45 days before departure minus admin fees. Cancellations within 45 days may forfeit deposit. Flight tickets are subject to airline cancellation policies once issued.",partialPaymentPercent:30,categories:["luxury","culture","adventure"]},{id:"rwanda-uganda-8-day-safari",slug:"rwanda-uganda-8-day-safari",name:"8 Days Rwanda–Uganda Safari",destination:"Kigali, Volcanoes, Lake Kivu, Bwindi, Queen Elizabeth & Kibale",country:"Rwanda and Uganda",region:"east-africa",duration:"8 Days / 7 Nights",durationDays:8,price:5470,currency:"USD",priceNote:"Per person mid-range, foreign non-resident rates. Includes two gorilla treks, golden monkey tracking, and chimpanzee trekking.",shortDescription:"Double gorilla encounters in Rwanda and Uganda, golden monkeys at Mgahinga, Lake Kivu, Queen Elizabeth wildlife, and chimpanzee trekking in Kibale — Kigali to Entebbe.",fullDescription:"This eight-day cross-border journey is the ultimate primate and wildlife circuit — start in Kigali with a moving city tour, trek mountain gorillas in Rwanda's Volcanoes National Park, cruise Lake Kivu, track golden monkeys where silver meets gold at Mgahinga, then cross into Uganda for a second gorilla trek in Bwindi, savannah game drives and a Kazinga Channel cruise in Queen Elizabeth, and afternoon chimpanzee trekking in Kibale. Kitum Cave Safaris handles permits, cross-border logistics, mid-range lodges, and a dedicated 4x4 driver-guide throughout.",travelType:"Wildlife & Primate Safari",availability:"Available year-round — gorilla and chimp permits must be booked well in advance",bestTimeToVisit:"Primate trekking runs year-round. Dry seasons (June–September and December–February) offer easier forest trails and clearer savannah viewing.",whatToBring:["Valid passport and East Africa Tourist Visa (Rwanda–Uganda)","Sturdy waterproof hiking boots","Long trousers and long-sleeved shirts in neutral colours","Light rain jacket, daypack, and gaiters for forest treks","Insect repellent, sun protection, and reusable water bottle","Binoculars and camera (no flash during primate viewing)","Yellow fever certificate (recommended)","Travel insurance documents"],faqs:[{question:"How many gorilla treks are included?",answer:"Two — one in Rwanda's Volcanoes National Park and one in Uganda's Bwindi Impenetrable National Park. Both gorilla permits are included in the package price quoted for foreign non-residents."},{question:"Do I need a separate visa for Rwanda and Uganda?",answer:"The East Africa Tourist Visa ($100) covers both Rwanda and Uganda for eligible nationalities. We advise on the latest requirements when you book."},{question:"How fit do I need to be?",answer:"Moderate fitness is recommended. Gorilla and chimp treks can last 2–6 hours on steep, muddy terrain. Golden monkey tracking is generally shorter but still involves forest walking."},{question:"Is the golden monkey trek included?",answer:"Yes — golden monkey tracking at Mgahinga Gorilla National Park is included, along with the chimpanzee trek in Kibale and all park fees listed in the itinerary."},...i.slice(0,1)],heroImage:"/images/4A9A8590.jpg",galleryImages:["/images/4A9A8590.jpg","/images/4A9A8591.jpg","/images/4A9A8592.jpg","/images/4A9A8560.jpg","/images/4A9A0474.jpg","/images/4A9A8545.jpg","/images/IMG-20260811-WA0090.jpg"],mapCoordinates:{lat:-.95,lng:30.05},mapZoom:7,included:["Rwanda gorilla permit (Volcanoes National Park)","Uganda gorilla permit (Bwindi Impenetrable National Park)","Chimpanzee permit (Kibale National Park)","Golden monkey permit (Mgahinga Gorilla National Park)","Park entrance fees (Mgahinga, Queen Elizabeth, Kibale, Bwindi)","7 nights mid-range accommodation with daily breakfast","4x4 Land Cruiser, fuel, and professional driver-guide","Cross-border COMESA insurance","Lake Kivu and Kazinga Channel boat safaris","Kigali city tour","East Africa Tourist Visa (Rwanda–Uganda)","Mineral water whilst on safari","All activities listed in the itinerary"],excluded:["International flights to/from home","Personal items and laundry","Tips for guides and lodge staff","Travel insurance","Soft drinks and alcoholic drinks","Optional activities not mentioned","Activities not listed in the itinerary"],itinerary:[{day:1,title:"Kigali City Tour & Transfer to Volcanoes",description:"After breakfast, embark on a Kigali city tour — visit the Kigali Genocide Memorial, a solemn tribute to the victims of the 1994 genocide, and the Belgian peacekeepers memorial honouring soldiers who lost their lives during the crisis. Enjoy a packed lunch while driving to Volcanoes National Park in northern Rwanda (approximately 2–3 hours). Check in at the lodge for overnight.",accommodation:"Da Vinci Gorilla Lodge",meals:"Breakfast"},{day:2,title:"Gorilla Trekking & Transfer to Lake Kivu",description:"After an early breakfast, transfer to park headquarters for a comprehensive briefing and allocation of your gorilla family. Hike through the forest with rangers to find a habituated group — the trek takes 2–6 hours depending on gorilla movements. Spend one hour observing them, then drive approximately 3 hours to Lake Kivu. Check in, refresh, and relax at the lodge.",accommodation:"Cormoran Lodge",meals:"Breakfast"},{day:3,title:"Lake Kivu Boat Safari & Transfer to Mgahinga",description:"After breakfast, enjoy a scenic boat tour on Lake Kivu — visit Napoleon Island, named for its distinctive shape and home to fruit bats, and a traditional fishing village to observe local methods. Check out after the boat safari and have lunch, then transfer to Mgahinga Gorilla National Park — where silver meets gold — for overnight at the lodge ahead of golden monkey tracking.",accommodation:"Travelers Rest Hotel",meals:"Breakfast"},{day:4,title:"Golden Monkey Tracking & Transfer to Bwindi",description:"After morning breakfast, trek into the forest in search of golden monkeys — trackers follow fresh bamboo shoots left from the previous day. Once found, spend one hour watching them leap through the trees. After lunch, transfer to Bwindi Impenetrable National Park. Check in at the lodge, refresh, and prepare for your second gorilla trek tomorrow.",accommodation:"Bakiga Lodge",meals:"Breakfast"},{day:5,title:"Bwindi Gorilla Trekking & Transfer to Queen Elizabeth",description:"Early breakfast, then head to Bwindi park headquarters for briefing before setting off with experienced guides in search of mountain gorillas. Spend an hour with these giants in their natural habitat. After the trek, enjoy packed lunch while driving to Queen Elizabeth National Park — Uganda's most popular and biodiverse safari destination (approximately 4–6 hours). Check in at the lodge on arrival.",accommodation:"Irungu Forest Safari Lodge",meals:"Breakfast"},{day:6,title:"Queen Elizabeth Game Drive & Kazinga Channel",description:"Very early breakfast, then a morning game drive on the savannah — lions, elephants, buffalo, leopards, and antelope are commonly sighted. In the afternoon, take a boat safari along the Kazinga Channel, consistently rich with hippos, crocodiles, elephants, buffalo, and birdlife along the shores. Return to the lodge for relaxation.",accommodation:"Irungu Forest Safari Lodge",meals:"Breakfast"},{day:7,title:"Transfer to Kibale & Chimpanzee Trekking",description:"After breakfast, transfer to Kibale National Park — the primate capital of the world with over 1,500 chimpanzees (approximately 1.5 hours). Check in at the lodge, relax, and prepare for afternoon chimpanzee trekking. Briefing at park headquarters, then trek from Kanyanchu Visitor Centre (from 3:30 pm) for 2–5 hours with expert guides to a habituated chimp group.",accommodation:"Isunga Lodge",meals:"Breakfast"},{day:8,title:"Transfer to Entebbe & Departure",description:"After breakfast, transfer to Kampala/Entebbe for drop-off in time for your evening flight — end of trip.",meals:"Breakfast"}],accommodation:"Da Vinci Gorilla Lodge · Cormoran Lodge · Travelers Rest · Bakiga Lodge · Irungu Forest Safari Lodge · Isunga Lodge (7 nights mid-range)",transport:"4x4 Land Cruiser with professional driver-guide; cross-border COMESA insurance; route Kigali–Musanze–Kivu–Kisoro–Bwindi–Queen Elizabeth–Kibale–Entebbe",importantInfo:["Minimum age for gorilla trekking is 15 years","Two gorilla permits included — book months in advance","Mid-range accommodation as quoted; upgrades available on request","Moderate fitness required for multiple forest treks across eight days"],bookingRequirements:["Valid passport (6+ months validity)","East Africa Tourist Visa or individual Rwanda/Uganda visas","Yellow fever vaccination certificate recommended","Travel insurance strongly recommended"],cancellationPolicy:"Deposit refundable up to 45 days before departure minus admin fees. Gorilla and chimp permits are subject to national park authority policies once issued — non-transferable in most cases.",partialPaymentPercent:30,featured:!0,categories:["wildlife","adventure","culture","nature"]},{id:"uganda-12-day-safari",slug:"12-days-uganda-safari",name:"12 Days Uganda Safari",destination:"Kidepo, Murchison Falls, Kibale, Queen Elizabeth, Bwindi & Lake Bunyonyi",country:"Uganda",region:"east-africa",duration:"12 Days / 11 Nights",durationDays:12,price:5195,currency:"USD",priceNote:"Per person mid-range, foreign non-resident rates. Includes gorilla and chimpanzee permits.",shortDescription:"Uganda's grand circuit — Source of the Nile, Sipi Falls, remote Kidepo, Murchison Falls, chimps in Kibale, Queen Elizabeth savannah, gorillas in Bwindi, and Lake Bunyonyi.",fullDescription:"This twelve-day journey covers Uganda's greatest hits in a single epic loop — from the Source of the Nile at Jinja and the waterfalls of Mount Elgon to the remote wilderness of Kidepo Valley, the thunder of Murchison Falls, chimpanzee tracking in Kibale, savannah game drives and Kazinga Channel cruises in Queen Elizabeth, mountain gorillas in Bwindi, and a serene finale on Lake Bunyonyi. Kitum Cave Safaris handles all permits, mid-range lodges, boat safaris, cultural experiences with the IK and Batwa communities, and a dedicated 4x4 driver-guide for the full 2,800 km circuit.",travelType:"Wildlife & Adventure Safari",availability:"Available year-round — gorilla and chimp permits must be booked well in advance",bestTimeToVisit:"June to September and December to February offer the driest roads and easiest trekking. Kidepo is rewarding year-round; we advise on seasonal conditions when you book.",whatToBring:["Valid passport and Uganda visa or East Africa Tourist Visa","Sturdy waterproof hiking boots for gorilla and chimp treks","Long trousers and neutral-coloured clothing","Light rain jacket, daypack, and sun protection","Insect repellent and reusable water bottle","Binoculars and camera (no flash during primate viewing)","Yellow fever certificate (recommended)","Travel insurance documents"],faqs:[{question:"Is this suitable for first-time safari travellers?",answer:"Yes — this is our most comprehensive Uganda itinerary, covering the country's iconic parks in a logical route with experienced driver-guides handling all logistics, permits, and lodge check-ins."},{question:"Are gorilla and chimp permits included?",answer:"Yes — your Bwindi gorilla permit and Kibale chimpanzee permit are included in the quoted price for foreign non-residents."},{question:"How much driving is involved?",answer:"This is a road safari covering approximately 2,800 km over twelve days, including long transfers to Kidepo and between parks. The route is scenic with regular breaks; flying segments can be quoted on request."},{question:"What cultural experiences are included?",answer:"A cultural walk with the IK people in Kidepo and a Batwa community experience near Bwindi are included in the package price."},...i.slice(0,1)],heroImage:"/images/4A9A0445.jpg",galleryImages:["/images/4A9A0445.jpg","/images/4A9A0474.jpg","/images/4A9A8590.jpg","/images/4A9A8591.jpg","/images/4A9A8545.jpg","/images/IMG-20260811-WA0099.jpg","/images/4A9A8600.jpg"],mapCoordinates:{lat:1.5,lng:32.5},mapZoom:6,included:["Gorilla permit (Bwindi Impenetrable National Park)","Chimpanzee permit (Kibale National Park)","Park entrance fees (Kidepo, Murchison, Queen Elizabeth, Mount Elgon, Bwindi, Kibale)","11 nights mid-range accommodation with daily breakfast","4x4 Land Cruiser, fuel, and professional driver-guide","Boat safaris (Nile, Kazinga Channel, Lake Bunyonyi)","Sipi Falls hike and Mount Elgon experience","IK cultural walk (Kidepo) and Batwa community experience (Bwindi)","Mineral water whilst on safari","All activities listed in the itinerary"],excluded:["International flights","Uganda visa fees","Personal items and laundry","Tips for guides and lodge staff","Soft drinks and alcoholic drinks","Travel insurance","Optional activities not mentioned"],itinerary:[{day:1,title:"Entebbe to Jinja & Mount Elgon",description:"Pick-up from Entebbe or your hotel. Transfer to Jinja (approximately 2 hours) for a boat ride to the Source of the Nile, visit a local craft shop, and lunch. Continue to Mount Elgon National Park near Mbale and check in for overnight.",accommodation:"Sipi River Lodge",meals:"Breakfast"},{day:2,title:"Mount Elgon & Sipi Falls",description:"After breakfast, briefing at park headquarters, then explore caves, hot springs, scenic viewpoints, and local walks. Drive to Sipi Falls (approximately 1–1.5 hours) for a series of three waterfalls set in lush greenery. Return to the lodge for overnight.",accommodation:"Sipi River Lodge",meals:"Breakfast"},{day:3,title:"Transfer to Kidepo Valley & Evening Game Drive",description:"Early breakfast, then transfer to Kidepo Valley National Park — Uganda's remote wilderness of arid savannah, rugged mountains, and exceptional wildlife including cheetahs, lions, leopards, bat-eared foxes, buffalo, giraffes, and zebras (approximately 7–8 hours via Mbale–Moroto). Lunch en route. Check in and prepare for an evening game drive along the Narus River valley.",accommodation:"Kidepo Savannah Lodge",meals:"Breakfast"},{day:4,title:"Kidepo Game Drive & IK Cultural Walk",description:"Morning game drive — buffalo herds, elephants, giraffes, lions, cheetahs, and more. Return to the lodge for lunch and relaxation. Afternoon cultural walk to visit the IK people in their homesteads — interact, learn about their pastoralist culture, food, and traditional dance. Overnight at the lodge.",accommodation:"Kidepo Savannah Lodge",meals:"Breakfast"},{day:5,title:"Transfer to Murchison Falls",description:"After breakfast, transfer to Murchison Falls National Park, home to the world's most powerful waterfall (approximately 7–9 hours on a scenic route). Lunch en route. Check in at the lodge, refresh, and relax.",accommodation:"Pakuba Safari Lodge",meals:"Breakfast"},{day:6,title:"Murchison Falls Game Drive & Boat Safari",description:"Early morning game drive — chance of big cats hunting, plus elephants, giraffes, buffalo, and 76 mammal species on the checklist. Lunch and relaxation at the lodge. Afternoon 3-hour boat safari on the Nile — schools of hippos, Nile crocodiles, elephants, buffalo, and abundant birdlife along the banks.",accommodation:"Pakuba Safari Lodge",meals:"Breakfast"},{day:7,title:"Transfer to Kibale National Park",description:"After breakfast, transfer to Kibale Forest National Park — home to over 1,500 chimpanzees and thirteen primate species including red colobus, Uganda mangabey, olive baboons, and black-and-white colobus (approximately 8 hours). Lunch break in Fort Portal. Check in at the lodge and prepare for tomorrow's chimp trek.",accommodation:"Isunga Lodge",meals:"Breakfast"},{day:8,title:"Chimpanzee Tracking & Queen Elizabeth",description:"Breakfast, then briefing at park headquarters before trekking into the forest with rangers to find a habituated chimp group (up to 3 hours). Receive your certificate, lunch, then transfer to Queen Elizabeth National Park (approximately 2–3 hours) with a stop at the Kikorongo equator. Late evening game drive on the Kasenyi plains or Mweya peninsula — elephants, kobs, and buffalo.",accommodation:"Bush Lodge",meals:"Breakfast"},{day:9,title:"Queen Elizabeth Game Drive & Kazinga Channel",description:"Morning game drive — lions, leopards, elephants, buffalo, and antelope. Return to the lodge before an afternoon 3-hour boat cruise on the Kazinga Channel — hippos, crocodiles, elephants, waterbucks, Uganda kobs, warthogs, and birdlife including fish eagles and kingfishers.",accommodation:"Bush Lodge",meals:"Breakfast"},{day:10,title:"Transfer to Bwindi & Batwa Experience",description:"After breakfast, transfer to Bwindi Impenetrable National Park via the Ishasha sector (approximately 3–4 hours) with packed lunch and a stop in Kabale. Check in at the lodge, then a cultural experience with the Batwa pygmies — indigenous forest people whose heritage is woven into Bwindi's story.",accommodation:"Bakiga Lodge",meals:"Breakfast"},{day:11,title:"Gorilla Trekking & Lake Bunyonyi",description:"Early breakfast, briefing at Bwindi park headquarters, then trek through dense forest with guides to find a habituated gorilla family. Spend one hour with the gentle giants. After the trek, transfer to Lake Bunyonyi — Uganda's deepest lake, formed 10,000 years ago and renowned for its islands and birdlife. Check in and relax.",accommodation:"Birdnest Resort",meals:"Breakfast"},{day:12,title:"Lake Bunyonyi & Return to Entebbe",description:"Morning canoe or boat safari exploring the islands — Punishment Island, Bwama Island, Njuyeera Island (home of missionary Dr Leonard Sharp), Bushara Island, and Kahugye Island with zebra and antelope. Drive back to Entebbe with a lunch stop at the equator, arriving in time for your evening flight — end of trip.",meals:"Breakfast"}],accommodation:"Sipi River Lodge · Kidepo Savannah Lodge · Pakuba Safari Lodge · Isunga Lodge · Bush Lodge · Bakiga Lodge · Birdnest Resort (11 nights mid-range)",transport:"4x4 Land Cruiser with professional driver-guide; route Entebbe–Sipi–Kidepo–Murchison–Kibale–Queen Elizabeth–Bwindi–Bunyonyi–Entebbe (~2,800 km)",importantInfo:["Long driving days — especially transfers to Kidepo and between northern and western parks","Gorilla and chimp permits included — book months in advance","Minimum age for gorilla trekking is 15 years","Mid-range accommodation as quoted; lodge upgrades available on request"],bookingRequirements:["Valid passport (6+ months validity)","Uganda visa or East Africa Tourist Visa","Yellow fever vaccination certificate recommended","Travel insurance strongly recommended"],cancellationPolicy:"Deposit refundable up to 45 days before departure minus admin fees. Gorilla and chimp permits are subject to Uganda Wildlife Authority policies once issued.",partialPaymentPercent:30,categories:["wildlife","adventure","culture","nature"]},{id:"uganda-rwanda-10-day-safari",slug:"10-days-uganda-rwanda-safari",name:"10 Days Uganda–Rwanda Safari",destination:"Murchison Falls, Kibale, Queen Elizabeth, Bwindi, Lake Kivu & Kigali",country:"Uganda and Rwanda",region:"east-africa",duration:"10 Days / 9 Nights",durationDays:10,price:4325,currency:"USD",priceNote:"Per person mid-range, foreign non-resident rates. Big Five safari plus gorilla and chimpanzee trekking.",shortDescription:"Uganda's Big Five at Murchison Falls, chimps in Kibale, savannah in Queen Elizabeth, gorillas in Bwindi, then Lake Kivu and Kigali — the classic Uganda–Rwanda circuit.",fullDescription:"This ten-day Uganda–Rwanda journey combines savannah Big Five game viewing with world-class primate encounters. Start at Murchison Falls with Ziwa Rhino Sanctuary and the Nile, track chimpanzees in Kibale and visit the Bigodi community, explore Queen Elizabeth's plains and Kazinga Channel, trek mountain gorillas in Bwindi, then cross into Rwanda for Lake Kivu and a Kigali city tour. Kitum Cave Safaris handles all permits, cross-border logistics, mid-range lodges, and a dedicated 4x4 driver-guide throughout.",travelType:"Wildlife & Primate Safari",availability:"Available year-round — gorilla and chimp permits must be booked well in advance",bestTimeToVisit:"June to September and December to February offer the best game viewing and forest trekking conditions. Year-round departures available.",whatToBring:["Valid passport and East Africa Tourist Visa (Uganda–Rwanda)","Sturdy waterproof hiking boots for gorilla and chimp treks","Long trousers and neutral-coloured clothing","Light rain jacket, daypack, and sun protection","Insect repellent and reusable water bottle","Binoculars and camera (no flash during primate viewing)","Yellow fever certificate (recommended)","Travel insurance documents"],faqs:[{question:"Does this trip include the Big Five?",answer:"Murchison Falls and Queen Elizabeth National Park offer strong chances of lions, leopards, elephants, and buffalo. Rhinos are visited at Ziwa Rhino Sanctuary en route to Murchison — rhino tracking on foot is an optional add-on."},{question:"Are gorilla and chimp permits included?",answer:"Yes — your Bwindi gorilla permit and Kibale chimpanzee permit are included in the quoted price for foreign non-residents."},{question:"How does the cross-border crossing work?",answer:"After gorilla trekking in Bwindi, you cross from Uganda into Rwanda at the Kyanika border near Kisoro and continue to Lake Kivu and Kigali. We handle COMESA insurance and border formalities."},{question:"Where does the trip start and end?",answer:"Pick-up is from Entebbe or your Kampala hotel on Day 1. The trip ends at Kigali International Airport on Day 10 after the city tour."},...i.slice(0,1)],heroImage:"/images/4A9A0474.jpg",galleryImages:["/images/4A9A0474.jpg","/images/4A9A0445.jpg","/images/4A9A8590.jpg","/images/4A9A9703.jpg","/images/IMG-20260811-WA0090.jpg","/images/4A9A8545.jpg"],mapCoordinates:{lat:.2,lng:31},mapZoom:7,included:["Gorilla permit (Bwindi Impenetrable National Park)","Chimpanzee permit (Kibale National Park)","Park entrance fees (Murchison, Kibale, Queen Elizabeth, Bwindi)","9 nights mid-range accommodation with daily breakfast","4x4 Land Cruiser, fuel, and professional driver-guide","Cross-border COMESA insurance","Boat safaris (Nile, Kazinga Channel, Lake Kivu)","Kigali city tour","Bigodi community cultural visit","East Africa Tourist Visa (Uganda–Rwanda)","Mineral water whilst on safari","All activities listed in the itinerary"],excluded:["International flights","Personal items and laundry","Tips for guides and lodge staff","Soft drinks and alcoholic drinks","Travel insurance","Optional rhino tracking at Ziwa (on request)","Optional activities not mentioned"],itinerary:[{day:1,title:"Transfer to Murchison Falls via Ziwa Rhinos",description:"After breakfast, pick-up from Entebbe or your hotel and transfer to Murchison Falls National Park via Kampala–Masindi (approximately 4 hours). Stop at Ziwa Rhino Sanctuary — a conservation area for endangered black rhinos (rhino tracking optional). Continue to the park and visit the top of the falls, where the Nile narrows through a rift valley chasm. Check in at the lodge for overnight.",accommodation:"Pakuba Safari Lodge",meals:"Breakfast"},{day:2,title:"Murchison Falls Game Drive & Nile Boat Safari",description:"Early breakfast, then a morning game drive across the park's expansive plains — lions, leopards, elephants, buffalo, giraffes, zebras, and antelope. After lunch, a boat safari along the Victoria Nile to the base of the falls, passing schools of hippos, crocodiles, and waterbirds (approximately 3 hours). Optional evening game drive. Overnight at the lodge.",accommodation:"Pakuba Safari Lodge",meals:"Breakfast"},{day:3,title:"Transfer to Kibale National Park",description:"After breakfast, transfer to Kibale National Park — one of Africa's best primate destinations (approximately 5–6 hours through scenic countryside and tea plantations). Lunch break in Fort Portal, then continue to the park. Check in, relax, and prepare for chimpanzee tracking tomorrow.",accommodation:"Isunga Lodge",meals:"Breakfast"},{day:4,title:"Chimpanzee Tracking & Bigodi Community Visit",description:"After breakfast, briefing at the park office, then trek into the forest with experienced guides to find a habituated chimpanzee troop. Spend quality time observing their social interactions. After lunch, a community walk to nearby Bigodi village — interact with local people, learn traditional customs, and enjoy dance and music performances showcasing the region's cultural heritage.",accommodation:"Isunga Lodge",meals:"Breakfast"},{day:5,title:"Transfer to Queen Elizabeth & Evening Game Drive",description:"After breakfast, transfer to Queen Elizabeth National Park with a photo stop at the Kikorongo equator monument. Check in at the lodge and relax. Evening game drive on the Kasenyi plains — search for lions, elephants, buffalo, and other wildlife until sunset.",accommodation:"Bush Lodge",meals:"Breakfast"},{day:6,title:"Queen Elizabeth Game Drive & Kazinga Channel",description:"Morning game drive — lions, leopards, elephants, buffalo, and antelope on the savannah. After lunch, a 3-hour boat safari on the Kazinga Channel — hippos, crocodiles, elephants and buffalo along the shores, plus waterbucks, Uganda kobs, warthogs, fish eagles, kingfishers, and abundant birdlife.",accommodation:"Bush Lodge",meals:"Breakfast"},{day:7,title:"Ishasha Tree-Climbing Lions & Transfer to Bwindi",description:"Morning game drive in the Ishasha sector, renowned for rare tree-climbing lions. Continue the scenic drive to Bwindi Impenetrable National Park (approximately 4–5 hours) with lunch en route. Check in at the lodge and prepare for gorilla trekking tomorrow.",accommodation:"Bakiga Lodge",meals:"Breakfast"},{day:8,title:"Gorilla Trekking & Transfer to Lake Kivu",description:"Early breakfast, then gorilla trekking in Bwindi with experienced rangers through dense forest until you find a habituated family — spend one hour with the gentle giants. Receive your certificate, then cross into Rwanda via the Kyanika border to Gisenyi on Lake Kivu. Check in at the lakeside resort and unwind.",accommodation:"Paradise Malahide",meals:"Breakfast"},{day:9,title:"Lake Kivu Boat Safari & Transfer to Kigali",description:"After breakfast, a scenic boat safari on Lake Kivu — visit Napoleon Island, home to fruit bats, and a traditional fishing village to observe local methods. Transfer to Kigali (approximately 3–4 hours). Check in at the lodge and relax.",accommodation:"Cormoran Lodge",meals:"Breakfast"},{day:10,title:"Kigali City Tour & Departure",description:"After early breakfast, visit the Kigali Genocide Memorial, the Belgian peacekeepers memorial, and vibrant cultural markets for insight into Rwanda's history and resilience. Transfer to Kigali International Airport for your departure — end of trip.",meals:"Breakfast"}],accommodation:"Pakuba Safari Lodge · Isunga Lodge · Bush Lodge · Bakiga Lodge · Paradise Malahide · Cormoran Lodge (9 nights mid-range)",transport:"4x4 Land Cruiser with professional driver-guide; route Entebbe–Murchison–Kibale–Queen Elizabeth–Bwindi–Kisoro–Lake Kivu–Kigali (~1,600 km)",importantInfo:["Trip starts in Entebbe/Kampala and ends in Kigali — book flights accordingly","Gorilla and chimp permits included — reserve months in advance","Rhino tracking at Ziwa is optional and priced separately on request","Minimum age for gorilla trekking is 15 years"],bookingRequirements:["Valid passport (6+ months validity)","East Africa Tourist Visa or individual Uganda/Rwanda visas","Yellow fever vaccination certificate recommended","Travel insurance strongly recommended"],cancellationPolicy:"Deposit refundable up to 45 days before departure minus admin fees. Gorilla and chimp permits are subject to national park authority policies once issued.",partialPaymentPercent:30,categories:["wildlife","adventure","culture","nature"]},{id:"uganda-5-day-mburo-bunyonyi-bwindi",slug:"5-days-uganda-gorilla-safari",name:"5 Days Uganda Gorilla Safari",destination:"Lake Mburo, Lake Bunyonyi & Bwindi Impenetrable National Park",country:"Uganda",region:"east-africa",duration:"5 Days / 4 Nights",durationDays:5,price:2780,currency:"USD",priceNote:"Per person sharing, foreign non-resident rates. Full board accommodation. Includes gorilla permit.",shortDescription:"Lake Mburo game drives, a Lake Bunyonyi island boat safari, a Batwa community visit, and mountain gorilla trekking in Bwindi.",fullDescription:"This five-day Uganda safari starts with an Equator stop and an evening game drive in Lake Mburo National Park — zebras, impalas, giraffe, and wetland birdlife — then climbs into the Kigezi Highlands for a canoe safari on Lake Bunyonyi. From there you continue to Bwindi Impenetrable National Park for a Batwa cultural experience and a full gorilla trek the following day, before returning to Entebbe or Kampala. Kitum Cave Safaris includes the gorilla permit, park fees, full-board lodges, and a 4x4 driver-guide throughout.",travelType:"Wildlife & Primate Safari",availability:"Available year-round — gorilla permits must be booked well in advance",bestTimeToVisit:"Gorilla trekking runs year-round. Dry seasons (June–September and December–February) offer easier forest trails and clearer savannah tracks in Lake Mburo.",whatToBring:["Sturdy waterproof hiking boots","Long trousers and long-sleeved shirt (neutral colours)","Light rain jacket, daypack, and packed-lunch bag for the trek","Insect repellent and sun protection","Reusable water bottle","Camera (no flash during gorilla viewing)","Yellow fever certificate (recommended)"],faqs:[{question:"Is the gorilla permit included?",answer:"Yes — the Bwindi gorilla trekking permit for a foreign non-resident is included in the package price."},{question:"Are lunch and dinner included?",answer:"Yes. This itinerary is quoted on full board — breakfast, lunch, and dinner at the lodges as listed. Day 5 includes breakfast at the lodge and a lunch stop at the Equator on the drive back."},{question:"How fit do I need to be for gorilla trekking?",answer:"A moderate level of fitness is recommended. Treks can last 2–6 hours on steep, muddy terrain. Porters are available to hire locally for extra support."},{question:"What is the minimum age?",answer:"Uganda Wildlife Authority requires gorilla trekkers to be at least 15 years old."},...i.slice(0,1)],heroImage:"/images/4A9A8590.jpg",galleryImages:["/images/4A9A8590.jpg","/images/4A9A8591.jpg","/images/4A9A8592.jpg","/images/IMG-20260811-WA0026.jpg","/images/4A9A8221.jpg","/images/4A9A8545.jpg"],mapCoordinates:{lat:-.6,lng:30.95},mapZoom:8,included:["4x4 safari vehicle, fuel, and professional driver-guide","Airport or hotel pickup and drop-off","Full board accommodation","Gorilla trekking permit","Park entrance fees","Bottled drinking water during the safari","Batwa community experience (Ruhija)","Lake Bunyonyi boat safari","Lake Mburo game drives","All activities listed in the itinerary"],excluded:["International flights","Travel documents and visas","Personal expenses","Alcoholic drinks","Laundry","Tips and gratuities","Activities not specifically mentioned"],itinerary:[{day:1,title:"Lake Mburo National Park",description:"Early pickup from your hotel in Kampala or Entebbe, then southwest toward Lake Mburo National Park through countryside, banana plantations, farms, villages, and long-horned Ankole cattle. Stop at the Equator crossing in Kayabwe for photographs, souvenirs, and refreshments, then continue to the park. Check in, lunch, and an evening game drive through savannah, woodland, and wetland — zebras, impalas, Uganda kobs, buffaloes, giraffes, elands, topis, warthogs, waterbucks, and birdlife. Return to the lodge for dinner.",accommodation:"Rwakobo Rock",meals:"Full board"},{day:2,title:"Lake Bunyonyi boat safari",description:"After early breakfast, a brief morning game drive, then transfer to Lake Bunyonyi — Uganda's deepest lake, known for more than 29 islands — through Mbarara and the Kigezi Highlands as savannah gives way to terraced farms and mountains. Check in, relax, then a canoe or boat safari among the islands, including Punishment Island, Bwama Island, Nyuyeera Island, and Bushara Island. Return to the lodge.",accommodation:"Arcadia Cottages",meals:"Full board"},{day:3,title:"Bwindi & Batwa experience",description:"After breakfast, transfer to Bwindi Impenetrable National Park, home to nearly half of the world's remaining mountain gorillas (approximately 1 hour). Check in, refresh, then an afternoon Batwa community experience — traditions, stories, music, dance, and forest knowledge. Return to the lodge and prepare for gorilla trekking.",accommodation:"Bakiga Lodge",meals:"Full board"},{day:4,title:"Gorilla trekking",description:"Early breakfast, then transfer to park headquarters for registration and briefing. Trek through Bwindi's rainforest — duration varies with the gorilla family's location. Once located, you have one hour with the family. Return to the lodge for lunch and rest. Carry drinking water, packed lunch if advised, a rain jacket, sturdy hiking shoes, and long clothing.",accommodation:"Bakiga Lodge",meals:"Full board"},{day:5,title:"Return to Entebbe",description:"Relaxed breakfast, then the drive back toward Kampala or Entebbe with a lunch stop at the Equator. Arrive in the afternoon or evening depending on traffic. Drop-off at your hotel or the airport — end of safari.",meals:"Breakfast; lunch en route"}],accommodation:"Rwakobo Rock (1 night) · Arcadia Cottages (1 night) · Bakiga Lodge (2 nights)",transport:"4x4 safari vehicle with professional driver-guide",importantInfo:["Gorilla trekking requires a reasonable level of fitness","Minimum age for gorilla trekking is 15 years","Gorilla permits are limited — book as early as you can","Pack sturdy hiking boots, long trousers, and rain gear"],bookingRequirements:["Valid passport","Gorilla trekking permit (arranged by Kitum Cave Safaris)","Yellow fever vaccination certificate recommended"],cancellationPolicy:"Deposit refundable up to 45 days before departure minus admin fees. Gorilla permits are subject to Uganda Wildlife Authority policies once issued.",partialPaymentPercent:30,featured:!0,categories:["wildlife","adventure","culture","nature"]},{id:"rwanda-3-day-gorilla-safari",slug:"3-days-rwanda-gorilla-safari",name:"3 Days Rwanda Gorilla Safari",destination:"Kigali & Volcanoes National Park",country:"Rwanda",region:"east-africa",duration:"3 Days / 2 Nights",durationDays:3,price:2543,currency:"USD",priceNote:"Per person sharing, foreign non-resident rates. Includes Rwanda gorilla permit. Day 1 bed & breakfast in Kigali; full board at Volcanoes.",shortDescription:"Kigali city highlights, the twin lakes of Burera and Ruhondo, and mountain gorilla trekking in Volcanoes National Park.",fullDescription:"A focused three-day Rwanda gorilla safari: arrive Kigali with a guided city tour when timing allows, then travel north through the volcanic highlands with a stop at Lakes Burera and Ruhondo before overnight at Volcanoes National Park. The next morning you trek from Kinigi headquarters with Rwanda Development Board rangers to spend one hour with a habituated mountain gorilla family, then return to Kigali for an evening flight. The quoted rate includes the gorilla permit, private 4x4, and listed meals.",travelType:"Wildlife & Primate Safari",availability:"Available year-round — Rwanda gorilla permits must be booked well in advance",bestTimeToVisit:"Trekking is possible year-round. June–September and December–February are generally drier on the forest trails.",whatToBring:["Sturdy waterproof hiking boots","Long trousers and long-sleeved shirt (neutral colours)","Light rain jacket, daypack, and packed lunch for the trek","Insect repellent and sun protection","Reusable water bottle","Camera (no flash during gorilla viewing)","Yellow fever certificate (recommended)"],faqs:[{question:"Is the Rwanda gorilla permit included?",answer:"Yes — the Volcanoes National Park gorilla permit is included in the package price quoted for a foreign non-resident."},{question:"Are lunch and dinner included?",answer:"Day 1 in Kigali is bed and breakfast. Day 2 at Volcanoes is breakfast, lunch, and dinner. Day 3 includes breakfast and a packed lunch for the trek."},{question:"Do I need a Rwanda visa?",answer:"Most travellers need a Rwanda visa. Visa fees are not included — we advise on the latest requirements when you book."},{question:"What is the minimum age?",answer:"Rwanda gorilla trekking is for visitors aged 15 years and above."},...i.slice(0,1)],heroImage:"/images/4A9A8592.jpg",galleryImages:["/images/4A9A8592.jpg","/images/4A9A8590.jpg","/images/4A9A8602.jpg","/images/4A9A8591.jpg","/images/4A9A8545.jpg","/images/4A9A8403.jpg"],mapCoordinates:{lat:-1.48,lng:29.5},mapZoom:9,included:["Kigali airport transfers","Private 4x4 safari vehicle","Full board accommodation","Gorilla permit","Twin lakes tour (Burera and Ruhondo)","Kigali city tour (timed with your arrival)","English-speaking driver-guide","Bottled drinking water"],excluded:["International flights","Rwanda visa","Tips","Personal expenses","Travel insurance","Activities not mentioned","Drinks not mentioned"],itinerary:[{day:1,title:"Arrival in Kigali",description:"Pickup at Kigali International Airport and transfer to your hotel. Depending on arrival time, a 4–5 hour guided Kigali city tour covering the city's culture, history, and modern centre — highlights may include the Kigali Genocide Memorial, Kimironko Market, and Kigali Convention Centre. Return to the hotel to rest ahead of the gorilla trek.",accommodation:"Hotel Villa Portofino, Kigali",meals:"Bed & breakfast"},{day:2,title:"Twin lakes & Volcanoes National Park",description:"Breakfast, then transfer toward Ruhengeri with a short tour of Lakes Burera and Ruhondo — rolling hills, clear water, and the volcanic skyline (approximately 3 hours' driving in this region). Continue to Volcanoes National Park, check in, lunch, and overnight.",accommodation:"Le Bambou Gorilla Lodge",meals:"Breakfast, lunch and dinner"},{day:3,title:"Gorilla tracking & departure",description:"Early breakfast, then transfer to Kinigi park headquarters for 7:00am registration and briefing by Rwanda Development Board rangers. Trek 2–6 hours through rainforest to a habituated gorilla family; once located, spend one hour observing them. Carry packed lunch and drinking water. Collect your certificate at headquarters, then transfer to Kigali for an evening international flight — end of tour.",meals:"Breakfast; packed lunch"}],accommodation:"Hotel Villa Portofino, Kigali (1 night) · Le Bambou Gorilla Lodge (1 night)",transport:"Private 4x4 safari vehicle with English-speaking driver-guide",importantInfo:["Gorilla briefing at Kinigi is at 7:00am — overnight near the park is required","Minimum age for gorilla trekking is 15 years","Kigali city tour length depends on your inbound flight time","Pack rain gear and sturdy boots for Volcanoes National Park"],bookingRequirements:["Valid passport (6+ months validity)","Rwanda visa as applicable","Gorilla permit (arranged by Kitum Cave Safaris)","Travel insurance strongly recommended"],cancellationPolicy:"Deposit refundable up to 45 days before departure minus admin fees. Gorilla permits are subject to Rwanda Development Board policies once issued.",partialPaymentPercent:30,featured:!0,categories:["wildlife","adventure","culture"]},{id:"uganda-7-day-wildlife-gorilla-chimp",slug:"7-days-uganda-wildlife-gorilla-chimpanzee-safari",name:"7 Days Uganda Wildlife, Gorilla & Chimpanzee Safari",destination:"Lake Mburo, Bwindi, Queen Elizabeth & Kibale Forest National Park",country:"Uganda",region:"east-africa",duration:"7 Days / 6 Nights",durationDays:7,price:3806,currency:"USD",priceNote:"Per person sharing, foreign non-resident rates. Full board accommodation. Includes gorilla and chimpanzee permits.",shortDescription:"Lake Mburo plains, Bwindi gorillas and Batwa culture, Queen Elizabeth game drives and the Kazinga Channel, then chimpanzees and Bigodi wetland in Kibale.",fullDescription:"A seven-day Uganda circuit combining savannah and primates: game drives in Lake Mburo, gorilla trekking and a Batwa experience in Bwindi, evening and morning game drives plus a Kazinga Channel boat safari in Queen Elizabeth National Park, then chimpanzee trekking and a Bigodi wetland walk in Kibale Forest. The quoted rate includes gorilla and chimpanzee permits, park fees, full-board lodges, boat safari, and a 4x4 driver-guide. Pickup and drop-off are Entebbe or Kampala.",travelType:"Wildlife & Primate Safari",availability:"Available year-round — gorilla and chimpanzee permits must be booked well in advance",bestTimeToVisit:"Dry seasons (June–September and December–February) offer easier roads and forest trails. Primate trekking runs year-round.",whatToBring:["Sturdy waterproof hiking boots","Long trousers and long-sleeved shirts in neutral colours","Light rain jacket, daypack, and sun protection","Insect repellent and reusable water bottle","Binoculars and camera (no flash during primate viewing)","Yellow fever certificate (recommended)"],faqs:[{question:"Are gorilla and chimpanzee permits included?",answer:"Yes — the Bwindi gorilla permit and Kibale chimpanzee permit for foreign non-residents are included in the quoted price."},{question:"Are lunch and dinner included?",answer:"Yes. This itinerary is quoted on full board — breakfast, lunch, and dinner as listed at the lodges, plus the Kazinga boat safari day and the return drive with a lunch stop."},{question:"What is the minimum age for gorilla trekking?",answer:"Uganda Wildlife Authority requires gorilla trekkers to be at least 15 years old."},...i.slice(0,1)],heroImage:"/images/4A9A0474.jpg",galleryImages:["/images/4A9A0474.jpg","/images/4A9A8590.jpg","/images/4A9A0486.jpg","/images/4A9A8591.jpg","/images/IMG-20260811-WA0026.jpg","/images/4A9A8221.jpg","/images/4A9A0460.jpg"],mapCoordinates:{lat:-.2,lng:30},mapZoom:7,included:["4x4 Land Cruiser, driver-guide, and fuel","Gorilla permit","Chimpanzee permit","Park fees","Full board accommodation","Mineral water","Kazinga Channel boat safari","Batwa cultural experience (Ruhija)","Bigodi wetland walk","All activities listed in the itinerary"],excluded:["International flights","Tips","Soft drinks or alcohol","Personal expenses"],itinerary:[{day:1,title:"Lake Mburo National Park",description:"Pickup from Entebbe or Kampala and transfer to Lake Mburo National Park — zebras, impalas, elands, buffaloes, warthogs, giraffes, hippos around the lakes, and many birds. Stop at the Equator for photographs and souvenirs, then continue via Mbarara. Check in, lunch, and an afternoon game drive.",accommodation:"Rwakobo Rock",meals:"Full board"},{day:2,title:"Transfer to Bwindi",description:"Early breakfast and a morning game drive, then check out and drive to Bwindi Impenetrable Forest through the hills of southwestern Uganda. Lunch stop in Kabale, then continue to the lodge to refresh and rest.",accommodation:"Bakiga Lodge",meals:"Full board"},{day:3,title:"Gorilla trekking & Batwa experience",description:"Breakfast, then briefing at Bwindi headquarters and allocation to a gorilla family. Trek until you find the group and spend one hour with them. Receive your certificate, return to the lodge for lunch, then a Batwa cultural experience — history, song, dance, and storytelling. Dinner at the lodge.",accommodation:"Bakiga Lodge",meals:"Full board"},{day:4,title:"Queen Elizabeth National Park",description:"After breakfast, transfer to Queen Elizabeth National Park through highland farms and changing landscapes. Lunch en route. On arrival, an evening game drive when timing allows, then check in at the lodge for dinner. Expect lions, elephants, buffaloes, Uganda kob, warthogs, hippos, and birdlife.",accommodation:"Kazinga Wilderness Lodge",meals:"Full board"},{day:5,title:"Kazinga Channel & transfer to Kibale",description:"Early breakfast and a morning game drive, then photography at the Kikorongo Equator. Continue to the Kazinga Channel boat cruise — hippos, crocodiles, elephants, buffaloes, and waterbirds along the banks. Lunch, check out, and transfer to Kibale Forest National Park for dinner at the lodge.",accommodation:"Kibale Forest Lodge",meals:"Full board"},{day:6,title:"Chimpanzee trekking & Bigodi wetland",description:"Breakfast, then park-office registration and briefing. Trek with guides to a chimpanzee troop and observe them from the permitted distance. Return for lunch. Afternoon guided walk at Bigodi Wetland Sanctuary — birds, primates, butterflies, and community conservation. Final night at the lodge.",accommodation:"Kibale Forest Lodge",meals:"Full board"},{day:7,title:"Return to Kampala or Entebbe",description:"After breakfast, drive toward Kampala or Entebbe with a short stop around Fort Portal — tea country and crater landscapes — and lunch en route. Afternoon or evening drop-off at your hotel or the airport depending on traffic — end of safari.",meals:"Breakfast; lunch en route"}],accommodation:"Rwakobo Rock (1 night) · Bakiga Lodge (2 nights) · Kazinga Wilderness Lodge (1 night) · Kibale Forest Lodge (2 nights)",transport:"4x4 Land Cruiser with professional driver-guide",importantInfo:["Gorilla and chimpanzee permits included — reserve months in advance","Minimum age for gorilla trekking is 15 years","Moderate fitness for forest treks on days 3 and 6","Full board as quoted; drinks not listed are extra"],bookingRequirements:["Valid passport","Gorilla and chimpanzee permits (arranged by Kitum Cave Safaris)","Yellow fever vaccination certificate recommended","Travel insurance strongly recommended"],cancellationPolicy:"Deposit refundable up to 45 days before departure minus admin fees. Gorilla and chimpanzee permits are subject to Uganda Wildlife Authority policies once issued.",partialPaymentPercent:30,featured:!0,categories:["wildlife","adventure","culture","nature"]}],t={question:"Are lunch and dinner included?",answer:"Breakfast is included. Lunch and dinner are available throughout the journey at extra cost — lodges and restaurants along the route serve them, and we can help you arrange them."},o="Breakfast included; lunch and dinner extra.",s=r.filter(e=>!/\[/.test(e.name)&&!/TO BE ADDED/i.test(e.fullDescription)).map(e=>{if(e.included.some(e=>/full board/i.test(e))){let a=e.priceNote?/full board/i.test(e.priceNote)?e.priceNote:`${e.priceNote} Full board accommodation.`:e.price>0?"Per person sharing. Full board accommodation.":e.priceNote;return{...e,priceNote:a}}let a=e.included.some(e=>/breakfast/i.test(e))?e.included:["Daily breakfast",...e.included],i=e.excluded.some(e=>/lunch/i.test(e))?e.excluded:["Lunch and dinner (available at extra cost — breakfast is included)",...e.excluded],n=e.faqs.some(e=>/lunch and dinner/i.test(e.question))?e.faqs:[t,...e.faqs],r=e.priceNote?e.priceNote.includes("Breakfast included")?e.priceNote:`${e.priceNote} ${o}`:e.price>0?`Per person sharing. ${o}`:e.priceNote;return{...e,included:a,excluded:i,faqs:n,priceNote:r,itinerary:e.itinerary.map(e=>({...e,meals:"Breakfast"}))}});e.s(["experienceCategories",0,[{id:"wildlife",title:"Wildlife",description:"Track gorillas, witness the great migration, encounter Africa's iconic species in their natural habitat.",image:"/images/4A9A8590.jpg"},{id:"adventure",title:"Adventure",description:"Swim with dolphins, snorkel crystal reefs, raft the Nile, and trek volcanic peaks — bold experiences for travelers who want more than the view from the vehicle.",image:"/images/IMG-20260811-WA0066.jpg"},{id:"culture",title:"Culture",description:"Walk with communities, discover ancient traditions, and connect with the living heritage of East Africa.",image:"/images/4A9A8221.jpg"},{id:"nature",title:"Nature",description:"From misty rainforests to volcanic lakes, explore landscapes that have shaped this continent.",image:"/images/4A9A8545.jpg"},{id:"luxury",title:"Luxury Escapes",description:"Premium lodges, private guides, and iconic settings — comfort woven into every horizon without losing authenticity.",image:"/images/IMG-20260811-WA0016.jpg"},{id:"international",title:"International Travel",description:"For East African travelers ready to discover destinations beyond the continent.",image:"/images/IMG-20260811-WA0012.jpg"}],"getDestinationSummary",0,function(e){let a=e?s.filter(a=>a.region===e):s,i={};return a.forEach(e=>{i[e.country]=(i[e.country]||0)+1}),Object.entries(i).map(([e,a])=>({country:e,count:a,slug:e.toLowerCase().replace(/\s+/g,"-")}))},"getJourneySearchMeta",0,function(){let e=s.filter(e=>"east-africa"===e.region),a=e.map(e=>e.durationDays),i=e.map(e=>e.price),n=Array.from(new Set(e.map(e=>e.travelType))).sort(),r=Array.from(new Set(a)).sort((e,a)=>e-a);return{minDays:Math.min(...a),maxDays:Math.max(...a),minPrice:Math.min(...i),maxPrice:Math.max(...i),types:n,durations:r}},"getPackagesByRegion",0,function(e){return s.filter(a=>a.region===e)},"packages",0,s,"siteConfig",0,a])}]);